call_show_sprite_resident:
    cp 32
    ret nc
    push af
    ld a, c
    cp 208
    jr c, .cssr_y_ok
    ld c, SPRITE_INVISIBLE
.cssr_y_ok:
    pop af
    push de
    ld l, a
    ld h, 0
    add hl, hl
    add hl, hl
    ld de, sprite_attributes
    add hl, de
    pop de
    ld (hl), c
    inc hl
    ld (hl), b
    inc hl
    ld (hl), d
    inc hl
    ld (hl), e
    ld a, 1
    ld (sprites_dirty), a
    ret

call_update_sprites_to_vram_resident:
    ld a, (sprites_dirty)
    or a
    ret z
    xor a
    ld (sprites_dirty), a
    ld hl, sprite_attributes
    ld de, SPRATR
    ld bc, 128
    call FAST_LDIRVM
    ret

call_clear_all_sprites_resident:
    ld hl, sprite_attributes
    ld b, 32
    ld a, 224
.casr_loop:
    ld (hl), a
    inc hl
    inc hl
    inc hl
    inc hl
    djnz .casr_loop
    ld a, 1
    ld (sprites_dirty), a
    ret

call_hide_sprite_resident:
    cp 32
    ret nc
    ld l, a
    ld h, 0
    add hl, hl
    add hl, hl
    ld de, sprite_attributes
    add hl, de
    ld (hl), 224
    ld a, 1
    ld (sprites_dirty), a
    ret

