    ld (time_second_frame_counter), a
    ld a, (interrupt_counter)
    ld (time_last_interrupt_counter), a
    ld a, (interrupt_counter+1)
    ld (time_last_interrupt_counter+1), a
    ld a, 1
    ld (hud_dirty_flag), a
world_local_timer_reset_done:
